<section class="panel admin-form mail-settings"><h2>分类信息审核通知</h2><p class="field-help">用户新发布或修改重提的信息进入待审核后，向指定邮箱发送通知。发送失败不会影响信息提交。</p>
<form method="post" class="stack-form"><?= csrfField() ?><input type="hidden" name="action" value="save">
<div class="form-grid">
<label>邮件通知<select name="enabled"><option value="1" <?= field('enabled',$mailConfig['enabled']?'1':'0')==='1'?'selected':'' ?>>启用</option><option value="0" <?= field('enabled',$mailConfig['enabled']?'1':'0')==='0'?'selected':'' ?>>关闭</option></select></label>
<label>收件邮箱<input type="email" name="recipient" value="<?= e(field('recipient',$mailConfig['recipient'])) ?>" maxlength="254" required></label>
<label>SMTP服务器<input name="host" value="<?= e(field('host',$mailConfig['host'])) ?>" maxlength="253" required></label>
<label>SMTP端口<input type="number" name="port" min="1" max="65535" value="<?= (int)field('port',$mailConfig['port']) ?>" required></label>
<label>加密方式<select name="security"><option value="ssl" <?= field('security',$mailConfig['security'])==='ssl'?'selected':'' ?>>SSL/TLS（通常465端口）</option><option value="tls" <?= field('security',$mailConfig['security'])==='tls'?'selected':'' ?>>STARTTLS（通常587端口）</option></select></label>
<label>发件账号<input type="email" name="username" value="<?= e(field('username',$mailConfig['username'])) ?>" maxlength="254" required></label>
<label>SMTP密码 / 授权码<input type="password" name="smtp_password" value="" maxlength="512" autocomplete="new-password" placeholder="<?= $mailConfig['has_password']?'已设置，留空保持原密码':'填写SMTP密码或授权码' ?>" <?= !$mailConfig['has_password']?'required':'' ?>><small class="field-help">密码不回显；修改后点击保存配置。</small></label>
</div><div class="form-actions"><button class="button">保存配置</button></div></form>
<div class="form-actions"><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="test"><button class="button button-outline">发送测试邮件</button></form><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="process"><button class="button button-outline">发送待发通知</button></form></div><p class="field-help">测试邮件使用已经保存的配置。显示“服务器已接收”表示SMTP发送成功，请同时检查收件邮箱。</p>
</section>
<section class="panel table-panel mail-history"><h2>最近发送记录 <small><?= $result['total'] ?> 封</small></h2><div class="table-scroll"><table><thead><tr><th>邮件主题 / 收件邮箱</th><th>状态</th><th>时间</th><th>操作</th></tr></thead><tbody>
<?php foreach($mailLogs as $log): ?><tr><td class="wide-cell"><?= e($log['subject']) ?><small class="field-help"><?= e($log['recipient']) ?></small></td><td><?= e(mailNotificationStatus($log['status'])) ?><small class="field-help">尝试 <?= (int)$log['attempts'] ?> 次</small><?php if($log['last_error']): ?><small class="field-help"><?= e($log['last_error']) ?></small><?php endif ?></td><td><?= e($log['created_at']) ?><?php if($log['sent_at']): ?><small class="field-help">发送：<?= e($log['sent_at']) ?></small><?php endif ?></td><td><div class="table-actions"><?php if($log['listing_id']): ?><a href="<?= e(adminUrl('listings',['status'=>'pending'])) ?>#listing-<?= (int)$log['listing_id'] ?>">查看审核</a><?php endif ?><?php if($log['status']==='failed' && $log['attempts']<3): ?><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="retry"><input type="hidden" name="id" value="<?= (int)$log['id'] ?>"><button class="text-button">重试</button></form><?php endif ?></div></td></tr><?php endforeach ?>
<?php if(!$mailLogs): ?><tr><td colspan="4">暂无邮件发送记录。</td></tr><?php endif ?></tbody></table></div><?php pagination($result) ?></section>
